#include <stdio.h>
#include <string.h>
int main() {
    char s1[1000], s2[1000];
    if (scanf("%s %s", s1, s2) == 2) {
        int l1 = strlen(s1);
        char best[1000] = ""; int max_len = 0;
        for (int i = 0; i < l1; i++) {
            for (int len = 1; i + len <= l1; len++) {
                char sub[1000]; strncpy(sub, s1 + i, len); sub[len] = '\0';
                if (strstr(s2, sub) && len > max_len) {
                    max_len = len; strcpy(best, sub);
                }
            }
        }
        if (max_len == 0) puts("-1");
        else puts(best);
    }
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    string s1, s2; if (cin >> s1 >> s2) {
        string longest = "";
        for (size_t i = 0; i < s1.length(); i++) {
            for (size_t j = i + 1; j <= s1.length(); j++) {
                string sub = s1.substr(i, j - i);
                if (s2.find(sub) != string::npos && sub.length() > longest.length()) {
                    longest = sub;
                }
            }
        }
        cout << (longest.empty() ? "-1" : longest) << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s1 = sc.next(), s2 = sc.next();
            String longest = "";
            for (int i = 0; i < s1.length(); i++) {
                for (int j = i + 1; j <= s1.length(); j++) {
                    String sub = s1.substring(i, j);
                    if (s2.contains(sub) && sub.length() > longest.length()) longest = sub;
                }
            }
            System.out.println(longest.isEmpty() ? "-1" : longest);
        }
    }
}

